/// 9. Commits the batch
///
/// No `JournalWriteBatch` wrapper is used; the raw `fjall::OwnedWriteBatch`
/// from `journal.database.batch()` is used directly.
fn issue_artifact(
    journal: &FjallJournal,
    artifact: AcceptedArtifact,
    policy: RuntimePolicy,
) -> Result<AcceptedArtifact, JournalError> {
    // Hold write_lock across the entire RMW sequence
    let write_guard = journal
        .write_lock
        .lock()
        .map_err(|_| JournalError::WriteLockPoisoned)?;

    // Read current counter
    let last = read_counter(journal)?;

    // Increment with overflow check
    let next = last
        .checked_add(1)
        .ok_or(JournalError::SequenceOverflow)?;

    // Build NonZeroU64 wrapper
    let seq = IssuedArtifactSequence::new(next);

    // Stamp artifact with issued sequence
    let mut stamped = artifact;
    stamped.accepted_at_seq = seq.to_event_seq();

    // Rebind digest after stamp (digest includes accepted_at_seq)
    bind_artifact_digest(&mut stamped)?;

    // Encode artifact to compiled IR record
    let ir =
        postcard::to_allocvec(&stamped).map_err(JournalError::PostcardEncodeFailed)?;
    let record = CompiledIrRecord {
        digest: stamped.digest,
        ir,
    };

    // Verify record digest before persisting
    crate::admission::verify_compiled_ir_record_digest(&record)?;

    // Encode record with envelope
    let encoded = crate::codec::encode_record(
        MAGIC_COMPILED_ARTIFACT,
        RecordKind::CompiledIr,
        0,
        &record,
        MAX_COMPILED_IR_BYTES,
    )?;

    // Create ONE raw OwnedWriteBatch for both counter and artifact
    let mut batch = journal.database.batch();

    // Stage counter update
    let counter_value = encode_counter_value(next);
    batch.put(
        &journal.artifact_acceptance,
        LAST_ISSUED_KEY,
        counter_value.as_ref(),
    );

    // Stage artifact record
    let artifact_key = compiled_ir_key(stamped.digest)?;
    batch.put(&journal.compiled_ir, &artifact_key, &encoded);

    // Apply durability policy
    if policy == RuntimePolicy::Strict {
